package cn.huankan.stream;
import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/qualification")public class QualificationAuditController {private final QualificationAuditService service;public QualificationAuditController(QualificationAuditService s){service=s;}public record Query(long after,int limit,UUID subscriptionId){}@PostMapping("/recompute")public Object recompute(@RequestBody Query q){return service.recompute(q.after(),q.limit(),q.subscriptionId());}@PostMapping("/status")public Object status(){return service.status();}@ExceptionHandler({IllegalArgumentException.class,org.springframework.dao.DataAccessException.class})public org.springframework.http.ResponseEntity<?> invalid(){return org.springframework.http.ResponseEntity.badRequest().body(Map.of("message","资格审计查询参数或订阅无效"));}}
